// Block (composition) — responsive feature cards for a marketing page.
// Card owns surface look; Grid and Stack own arrangement.
import type { ReactNode, Ref } from "react";
import { Card } from "../components/Card";
import { Grid } from "../layouts/Grid";
import type { Responsive } from "../layouts/responsive";
import { Stack } from "../layouts/Stack";
import "./FeatureGrid.css";

export interface FeatureGridProps {
  /** Features shown as individual cards. */
  features: {
    icon?: ReactNode;
    title: string;
    description: string;
  }[];
  /** Responsive number of equal-width feature columns. */
  columns?: Responsive<number>;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function FeatureGrid({
  features,
  columns = { small: 1, medium: 3 },
  className,
  ref,
}: FeatureGridProps) {
  return (
    <Grid
      as="section"
      ref={ref}
      columns={columns}
      gap="medium"
      aria-label="Features"
      className={className ? `sd-featuregrid ${className}` : "sd-featuregrid"}
    >
      {features.map((feature) => (
        <Card key={feature.title}>
          <Stack gap="small" className="sd-featuregrid__content">
            {feature.icon}
            {/* spacing: attachment — the glyph heads the title under it.
                The name and its supporting line are ONE unit, so they group at `x-small` while
                the card around them sits a rung looser. */}
            <>
              <Stack gap="x-small" className="sd-featuregrid__heading">
                <h3 className="sd-featuregrid__title sd-type-title-medium">{feature.title}</h3>
                <p className="sd-featuregrid__description sd-type-body-medium">
                  {feature.description}
                </p>
              </Stack>
            </>
          </Stack>
        </Card>
      ))}
    </Grid>
  );
}

/* FeatureGrid.css — .sd-featuregrid (Block)
   Arrangement only: fills the available section width and resets text margins. */
.sd-featuregrid {
  width: 100%;
}

.sd-featuregrid__title,
.sd-featuregrid__description {
  margin: 0;
}

.sd-featuregrid__description {
  color: var(--sd-color-text-muted);
}
